/**
 * Standalone Calendar UI — no portal, no input, just the panel.
 * Used by <DatePicker> (inside a portal popup) and dashboard widgets.
 *
 * Three views: day → month → year (drill-down via the header).
 */
import { ChevronLeft, ChevronRight } from 'lucide-react'
import { useMemo, useState } from 'react'

import { useMounted } from '~/hooks/use-mounted'
import { cx } from '~/lib/cx'

import styles from './calendar.module.scss'
import {
  buildDayGrid,
  cellToIso,
  DAY_NAMES_SHORT,
  MONTH_NAMES_FULL,
  MONTH_NAMES_SHORT,
  parseIso,
  todayIso,
} from './calendar-utils'

export interface CalendarProps {
  /** Selected ISO date YYYY-MM-DD (or '') */
  value?: string
  /** Called when user clicks a day */
  onSelect?: (iso: string) => void
  /** Disable dates before this ISO */
  min?: string
  /** Disable dates after this ISO */
  max?: string
  /** Show "Today" shortcut in the footer */
  showToday?: boolean
  /** Extra class on the root div */
  className?: string
  /**
   * If provided, the calendar starts at this year/month instead of the
   * selected value (or today). Useful for controlled external state.
   */
  initialYear?: number
  initialMonth?: number
  /**
   * ISO date used to mark "today" (YYYY-MM-DD). Pass a server-computed value
   * to keep server and client output identical.
   */
  today?: string
}

function seedDate(
  value: string | undefined,
  initialYear: number | undefined,
  initialMonth: number | undefined,
  todayDt: Date,
): Date {
  const sel = parseIso(value ?? '')
  if (sel) return sel
  if (initialYear !== undefined && initialMonth !== undefined) {
    return new Date(initialYear, initialMonth, 1)
  }
  return todayDt
}

export function Calendar({
  value,
  onSelect,
  min,
  max,
  showToday = true,
  className,
  initialYear,
  initialMonth,
  today: todayProp,
}: CalendarProps) {
  const mounted = useMounted()
  const providedToday = parseIso(todayProp ?? '') ? todayProp! : ''
  const today = providedToday || todayIso()
  const todayDt = parseIso(today)!

  const seeded = seedDate(value, initialYear, initialMonth, todayDt)
  const [cursorYear, setCursorYear] = useState(() => seeded.getFullYear())
  const [cursorMonth, setCursorMonth] = useState(() => seeded.getMonth())
  const [view, setView] = useState<'day' | 'month' | 'year'>('day')

  const selectedIso = value ?? ''
  // Hide "today" markers until hydration so a server in another timezone
  // cannot render a different day than the client. An explicit `today` prop
  // is deterministic and is kept for both renders.
  const displayToday = mounted ? today : providedToday
  const displayTodayDt = parseIso(displayToday)
  const hasExplicitSeed =
    Boolean(value) ||
    (initialYear !== undefined && initialMonth !== undefined) ||
    Boolean(providedToday)

  const prevMonth = () => {
    if (cursorMonth === 0) {
      setCursorYear((y) => y - 1)
      setCursorMonth(11)
    } else {
      setCursorMonth((m) => m - 1)
    }
  }
  const nextMonth = () => {
    if (cursorMonth === 11) {
      setCursorYear((y) => y + 1)
      setCursorMonth(0)
    } else {
      setCursorMonth((m) => m + 1)
    }
  }
  const prevYear = () => setCursorYear((y) => y - 1)
  const nextYear = () => setCursorYear((y) => y + 1)

  const decadeStart = (y: number) => Math.floor(y / 12) * 12
  const prevDecade = () => setCursorYear((y) => y - 12)
  const nextDecade = () => setCursorYear((y) => y + 12)

  const dayGrid = useMemo(
    () => buildDayGrid(cursorYear, cursorMonth),
    [cursorYear, cursorMonth],
  )
  const yearGrid = useMemo(() => {
    const s = decadeStart(cursorYear)
    return Array.from({ length: 12 }, (_, i) => s + i)
  }, [cursorYear])

  // Without a value, initial month or explicit `today`, the starting month is
  // only knowable on the client — render nothing on the server so the markup
  // cannot disagree with the hydrated output.
  if (!mounted && !hasExplicitSeed) return null

  function isDisabled(iso: string) {
    if (min && iso < min) return true
    if (max && iso > max) return true
    return false
  }

  function handleDayClick(iso: string) {
    if (isDisabled(iso)) return
    onSelect?.(iso)
  }

  return (
    <div className={cx(styles.root, className)}>
      {view === 'day' ? (
        <>
          <div className={styles.header}>
            <button
              type="button"
              onClick={prevMonth}
              className={styles.navButton}
              aria-label="Previous month"
            >
              <ChevronLeft aria-hidden size={15} />
            </button>
            <button
              type="button"
              onClick={() => setView('month')}
              className={styles.headerButton}
            >
              {MONTH_NAMES_FULL[cursorMonth]} {cursorYear}
            </button>
            <button
              type="button"
              onClick={nextMonth}
              className={styles.navButton}
              aria-label="Next month"
            >
              <ChevronRight aria-hidden size={15} />
            </button>
          </div>

          <div className={styles.weekdays}>
            {DAY_NAMES_SHORT.map((name) => (
              <div key={name} className={styles.weekday}>
                <span className={styles.weekdayLabel}>{name}</span>
              </div>
            ))}
          </div>

          <div className={styles.grid}>
            {dayGrid.map((cell) => {
              const iso = cellToIso(cell)
              const isSel = iso === selectedIso
              const isToday = iso === displayToday
              const isDis = isDisabled(iso)

              return (
                <div key={iso} className={styles.dayCell}>
                  <button
                    type="button"
                    disabled={isDis}
                    onClick={() => handleDayClick(iso)}
                    aria-label={iso}
                    aria-pressed={isSel}
                    className={cx(
                      styles.day,
                      isDis && styles.dayDisabled,
                      !isDis && isSel && styles.daySelected,
                      !isDis && !isSel && isToday && styles.dayToday,
                      !isDis && !isSel && !isToday && cell.outside && styles.dayOutside,
                    )}
                  >
                    {cell.day}
                  </button>
                </div>
              )
            })}
          </div>

          {showToday ? (
            <div className={styles.footer}>
              <button
                type="button"
                disabled={isDisabled(displayToday)}
                onClick={() => {
                  setCursorYear(todayDt.getFullYear())
                  setCursorMonth(todayDt.getMonth())
                  handleDayClick(today)
                }}
                className={styles.todayButton}
              >
                Today
              </button>
            </div>
          ) : null}
        </>
      ) : null}

      {view === 'month' ? (
        <>
          <div className={styles.header}>
            <button
              type="button"
              onClick={prevYear}
              className={styles.navButton}
              aria-label="Previous year"
            >
              <ChevronLeft aria-hidden size={15} />
            </button>
            <button
              type="button"
              onClick={() => setView('year')}
              className={styles.headerButton}
            >
              {cursorYear}
            </button>
            <button
              type="button"
              onClick={nextYear}
              className={styles.navButton}
              aria-label="Next year"
            >
              <ChevronRight aria-hidden size={15} />
            </button>
          </div>

          <div className={styles.choiceGrid}>
            {MONTH_NAMES_SHORT.map((name, i) => {
              const d = parseIso(selectedIso)
              const isSel = d?.getFullYear() === cursorYear && d?.getMonth() === i
              const isNow =
                displayTodayDt?.getFullYear() === cursorYear &&
                displayTodayDt?.getMonth() === i

              return (
                <button
                  key={name}
                  type="button"
                  onClick={() => {
                    setCursorMonth(i)
                    setView('day')
                  }}
                  aria-pressed={isSel}
                  className={cx(
                    styles.choice,
                    isSel && styles.choiceSelected,
                    !isSel && isNow && styles.choiceToday,
                  )}
                >
                  {name}
                </button>
              )
            })}
          </div>
        </>
      ) : null}

      {view === 'year' ? (
        <>
          <div className={styles.header}>
            <button
              type="button"
              onClick={prevDecade}
              className={styles.navButton}
              aria-label="Previous decade"
            >
              <ChevronLeft aria-hidden size={15} />
            </button>
            <div className={cx(styles.headerButton, styles.headerStatic)}>
              {yearGrid[0]} – {yearGrid[11]}
            </div>
            <button
              type="button"
              onClick={nextDecade}
              className={styles.navButton}
              aria-label="Next decade"
            >
              <ChevronRight aria-hidden size={15} />
            </button>
          </div>

          <div className={styles.choiceGrid}>
            {yearGrid.map((yr) => {
              const isSel = parseIso(selectedIso)?.getFullYear() === yr
              const isNow = displayTodayDt?.getFullYear() === yr

              return (
                <button
                  key={yr}
                  type="button"
                  onClick={() => {
                    setCursorYear(yr)
                    setView('month')
                  }}
                  aria-pressed={isSel}
                  className={cx(
                    styles.choice,
                    isSel && styles.choiceSelected,
                    !isSel && isNow && styles.choiceToday,
                  )}
                >
                  {yr}
                </button>
              )
            })}
          </div>
        </>
      ) : null}
    </div>
  )
}

@use 'styles' as vz;

.root {
  width: 100%;
  color: vz.color('foreground');
  font-size: vz.font-size('sm');
  user-select: none;
}

.header {
  display: flex;
  align-items: center;
  gap: vz.space(1);
  margin-block-end: vz.space(4);
}

.nav-button {
  display: inline-flex;
  flex: none;
  align-items: center;
  justify-content: center;
  width: vz.space(8);
  height: vz.space(8);
  padding: 0;
  border: 0;
  border-radius: vz.radius('xl');
  background: transparent;
  color: vz.color('muted-foreground');
  cursor: pointer;
  transition:
    background-color vz.duration('fast') vz.ease('out'),
    color vz.duration('fast') vz.ease('out');

  @include vz.hover {
    background: vz.color('accent');
    color: vz.color('foreground');
  }

  @include vz.focus-ring(2px, 2px, 0.6);
}

.header-button {
  flex: 1;
  padding-block: vz.space(1.5);
  padding-inline: vz.space(2);
  border: 0;
  border-radius: vz.radius('xl');
  background: transparent;
  color: vz.color('foreground');
  font-family: inherit;
  font-size: vz.font-size('sm');
  font-weight: 600;
  text-align: center;
  cursor: pointer;
  transition:
    background-color vz.duration('fast') vz.ease('out'),
    color vz.duration('fast') vz.ease('out');

  @include vz.hover {
    background: vz.color('accent');
  }

  @include vz.focus-ring(2px, 2px, 0.6);
}

.header-static {
  cursor: default;

  @include vz.hover {
    background: transparent;
  }
}

.weekdays {
  display: grid;
  grid-template-columns: repeat(7, minmax(0, 1fr));
  margin-block-end: vz.space(1);
}

.weekday {
  display: flex;
  align-items: center;
  justify-content: center;
  height: vz.space(8);
}

.weekday-label {
  color: vz.color('muted-foreground');
  font-size: 0.6875rem;
  font-weight: 600;
  letter-spacing: 0.02em;
  text-transform: uppercase;
}

.grid {
  display: grid;
  grid-template-columns: repeat(7, minmax(0, 1fr));
}

.day-cell {
  display: flex;
  align-items: center;
  justify-content: center;
  padding-block: vz.space(0.5);
}

.day {
  position: relative;
  display: inline-flex;
  align-items: center;
  justify-content: center;
  width: vz.space(9);
  height: vz.space(9);
  padding: 0;
  border: 0;
  border-radius: vz.radius('full');
  background: transparent;
  color: vz.color('foreground');
  font-family: inherit;
  font-size: 0.8125rem;
  font-weight: 500;
  cursor: pointer;
  transition:
    background-color vz.duration('fast') vz.ease('out'),
    color vz.duration('fast') vz.ease('out'),
    box-shadow vz.duration('fast') vz.ease('out');

  @include vz.hover {
    background: vz.color('accent');
  }

  @include vz.focus-ring(2px, 2px, 0.6);
}

.day-outside {
  color: vz.color('muted-foreground');
}

.day-selected {
  background: vz.color('primary');
  color: vz.color('primary-foreground');
  box-shadow: vz.elevation(1);

  @include vz.hover {
    background: vz.color('primary');
  }
}

.day-today {
  font-weight: 600;
  box-shadow:
    0 0 0 1px vz.color('background'),
    0 0 0 3px vz.color('ring');
}

.day-disabled {
  opacity: 0.25;
  cursor: not-allowed;
  pointer-events: none;
}

.choice-grid {
  display: grid;
  grid-template-columns: repeat(3, minmax(0, 1fr));
  gap: vz.space(2);
}

.choice {
  height: vz.space(11);
  padding: 0;
  border: 0;
  border-radius: vz.radius('xl');
  background: transparent;
  color: vz.color('foreground');
  font-family: inherit;
  font-size: vz.font-size('sm');
  font-weight: 500;
  cursor: pointer;
  transition:
    background-color vz.duration('fast') vz.ease('out'),
    color vz.duration('fast') vz.ease('out'),
    box-shadow vz.duration('fast') vz.ease('out');

  @include vz.hover {
    background: vz.color('accent');
  }

  @include vz.focus-ring(2px, 2px, 0.6);
}

.choice-selected {
  background: vz.color('primary');
  color: vz.color('primary-foreground');
  box-shadow: vz.elevation(1);

  @include vz.hover {
    background: vz.color('primary');
  }
}

.choice-today {
  font-weight: 600;
  box-shadow:
    0 0 0 1px vz.color('background'),
    0 0 0 3px vz.color('ring');
}

.footer {
  display: flex;
  justify-content: center;
  margin-block-start: vz.space(4);
  padding-block-start: vz.space(3);
  border-top: 1px solid vz.color('border');
}

.today-button {
  padding: vz.space(1) vz.space(2);
  border: 0;
  border-radius: vz.radius('md');
  background: transparent;
  color: vz.color('foreground');
  font-family: inherit;
  font-size: 0.8125rem;
  font-weight: 500;
  cursor: pointer;
  transition: background-color vz.duration('fast') vz.ease('out');

  @include vz.hover {
    background: vz.color('accent');
  }

  @include vz.focus-ring(2px, 2px, 0.6);

  @include vz.disabled {
    opacity: 0.3;
    cursor: not-allowed;
    background: transparent;
  }
}

/**
 * Calendar constants and date helpers shared by <Calendar> and <DatePicker>.
 * Kept in a component-free module so the component file can Fast Refresh.
 */

export const DAY_NAMES_SHORT = ['Su', 'Mo', 'Tu', 'We', 'Th', 'Fr', 'Sa'] as const

export const MONTH_NAMES_FULL = [
  'January',
  'February',
  'March',
  'April',
  'May',
  'June',
  'July',
  'August',
  'September',
  'October',
  'November',
  'December',
] as const

export const MONTH_NAMES_SHORT = [
  'Jan',
  'Feb',
  'Mar',
  'Apr',
  'May',
  'Jun',
  'Jul',
  'Aug',
  'Sep',
  'Oct',
  'Nov',
  'Dec',
] as const

export function todayIso(): string {
  const t = new Date()
  return `${t.getFullYear()}-${String(t.getMonth() + 1).padStart(2, '0')}-${String(t.getDate()).padStart(2, '0')}`
}

export function parseIso(iso: string): Date | null {
  if (!iso) return null
  const dt = new Date(`${iso}T00:00:00`)
  return isNaN(dt.getTime()) ? null : dt
}

export interface DayCell {
  year: number
  month: number // 0-indexed
  day: number
  outside: boolean
}

export function buildDayGrid(year: number, month: number): DayCell[] {
  const firstWeekday = new Date(year, month, 1).getDay()
  const daysInMonth = new Date(year, month + 1, 0).getDate()
  const daysInPrev = new Date(year, month, 0).getDate()
  const cells: DayCell[] = []

  for (let i = firstWeekday - 1; i >= 0; i--) {
    cells.push({
      year: month === 0 ? year - 1 : year,
      month: month === 0 ? 11 : month - 1,
      day: daysInPrev - i,
      outside: true,
    })
  }
  for (let d = 1; d <= daysInMonth; d++) {
    cells.push({ year, month, day: d, outside: false })
  }
  const trailing = 42 - cells.length
  for (let d = 1; d <= trailing; d++) {
    cells.push({
      year: month === 11 ? year + 1 : year,
      month: month === 11 ? 0 : month + 1,
      day: d,
      outside: true,
    })
  }
  return cells
}

export function cellToIso(c: DayCell): string {
  return `${c.year}-${String(c.month + 1).padStart(2, '0')}-${String(c.day).padStart(2, '0')}`
}
